//! `DerivedAccount` and `kms::Service::route` provide the funding sender
//! consumed by `FundingEnvironment::from_env`, `ChainFunding::from_env`, and
//! `EvmSender`.
//!
//! The three core funding variables cross the real process environment. Fresh
//! decodes observe changed listeners and key material, and reject malformed
//! URLs, scalars, KMS identifiers and ambiguous signer sources. The KMS key is
//! generated by the real service, reopened from its sealed journal, and loaded
//! and used through authenticated TLS. No funding RPC or signer is replaced.
//!
//! The funding sender is provided by `layerx_platform_internal::evm_sender`.

include!("../src/main.rs");

mod proof {
    use super::chain_fund::{
        ChainFunding, FundingEnvironment, LAYERX_CORE_CHAIN_RPC_URL,
        LAYERX_CORE_FUNDING_SENDER_KEY_FILE, LAYERX_CORE_FUNDING_SENDER_KMS_KEY_ID,
    };
    use layerx_crypto::account_derivation::derive_from_seed;
    use layerx_platform_internal::{
        base64,
        evm_sender::{EvmSender, EvmSenderError},
        http, kms,
        seal::SealKey,
        tls,
    };
    use std::collections::BTreeMap;
    use std::env;
    use std::ffi::OsString;
    use std::fs;
    use std::io::Write;
    use std::net::TcpListener;
    use std::os::unix::fs::{DirBuilderExt, OpenOptionsExt};
    use std::path::{Path, PathBuf};
    use std::process::Command;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;
    use std::thread::{self, JoinHandle};
    use std::time::Duration;
    use zeroize::Zeroizing;

    const PREFIX: &str = "LAYERX_CORE_FUNDING_SENDER";
    const TOKEN: &str = "core-env-proof-kms-token";

    struct Fixture {
        root: PathBuf,
        environment: BTreeMap<String, Option<OsString>>,
    }

    impl Fixture {
        fn new() -> Self {
            let suffix = layerx_platform_internal::secret::random_hex(12)
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
            let root = env::temp_dir().join(format!("core-env-proof-{}", suffix.as_str()));
            fs::DirBuilder::new()
                .mode(0o700)
                .create(&root)
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
            let mut fixture = Self {
                root,
                environment: BTreeMap::new(),
            };
            for name in [
                LAYERX_CORE_CHAIN_RPC_URL,
                LAYERX_CORE_FUNDING_SENDER_KEY_FILE,
                LAYERX_CORE_FUNDING_SENDER_KMS_KEY_ID,
            ] {
                fixture.set(name, None);
            }
            for suffix in [
                "UPSTREAM_URL",
                "UPSTREAM_CA_DER",
                "UPSTREAM_TOKEN_FILE",
                "UPSTREAM_CLIENT_IDENTITY_PKCS12",
                "UPSTREAM_CLIENT_IDENTITY_PASSWORD_FILE",
                "UPSTREAM_COOKIE_FILE",
                "TLS_CERT_DER",
                "TLS_KEY_DER",
                "CLIENT_CA_DER",
            ] {
                fixture.set(&format!("{PREFIX}_{suffix}"), None);
            }
            fixture
        }

        fn set(&mut self, name: &str, value: Option<&std::ffi::OsStr>) {
            self.environment
                .entry(name.to_owned())
                .or_insert_with(|| env::var_os(name));
            if let Some(value) = value {
                env::set_var(name, value);
            } else {
                env::remove_var(name);
            }
        }

        fn text(&mut self, name: &str, value: &str) {
            self.set(name, Some(value.as_ref()));
        }

        fn private_file(&self, name: &str, contents: &[u8]) -> PathBuf {
            let path = self.root.join(name);
            fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .mode(0o600)
                .open(&path)
                .unwrap_or_else(|error| panic!("required value: {error:?}"))
                .write_all(contents)
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
            path
        }
    }

    impl Drop for Fixture {
        fn drop(&mut self) {
            for (name, value) in &self.environment {
                if let Some(value) = value {
                    env::set_var(name, value);
                } else {
                    env::remove_var(name);
                }
            }
            fs::remove_dir_all(&self.root)
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
        }
    }

    fn openssl(directory: &Path, arguments: &[&str]) {
        let output = Command::new("openssl")
            .current_dir(directory)
            .args(arguments)
            .output()
            .unwrap_or_else(|error| {
                panic!(
                    "{}: {error:?}",
                    "proof_core_env_vars.rs: openssl must produce the local KMS certificates"
                )
            });
        assert!(
            output.status.success(),
            "openssl: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    fn certificates(directory: &Path) {
        openssl(
            directory,
            &[
                "req",
                "-x509",
                "-newkey",
                "rsa:2048",
                "-nodes",
                "-keyout",
                "ca.key",
                "-out",
                "ca.pem",
                "-days",
                "1",
                "-subj",
                "/CN=Core Env Proof CA",
                "-addext",
                "basicConstraints=critical,CA:TRUE",
            ],
        );
        fs::write(directory.join("server.ext"), "basicConstraints=critical,CA:FALSE\nsubjectAltName=DNS:localhost\nextendedKeyUsage=serverAuth\n").unwrap_or_else(|error| panic!("required value: {error:?}"));
        fs::write(
            directory.join("client.ext"),
            "basicConstraints=critical,CA:FALSE\nextendedKeyUsage=clientAuth\n",
        )
        .unwrap_or_else(|error| panic!("required value: {error:?}"));
        for name in ["server", "client"] {
            openssl(
                directory,
                &[
                    "req",
                    "-new",
                    "-newkey",
                    "rsa:2048",
                    "-nodes",
                    "-keyout",
                    &format!("{name}.key"),
                    "-out",
                    &format!("{name}.csr"),
                    "-subj",
                    &format!("/CN={name}"),
                ],
            );
            openssl(
                directory,
                &[
                    "x509",
                    "-req",
                    "-in",
                    &format!("{name}.csr"),
                    "-CA",
                    "ca.pem",
                    "-CAkey",
                    "ca.key",
                    "-CAcreateserial",
                    "-out",
                    &format!("{name}.pem"),
                    "-days",
                    "1",
                    "-extfile",
                    &format!("{name}.ext"),
                ],
            );
        }
        certificate_derivatives(directory);
    }

    fn certificate_derivatives(directory: &Path) {
        for name in ["server", "ca"] {
            openssl(
                directory,
                &[
                    "x509",
                    "-in",
                    &format!("{name}.pem"),
                    "-outform",
                    "DER",
                    "-out",
                    &format!("{name}.der"),
                ],
            );
        }
        openssl(
            directory,
            &[
                "pkcs8",
                "-topk8",
                "-nocrypt",
                "-in",
                "server.key",
                "-outform",
                "DER",
                "-out",
                "server-key.der",
            ],
        );
        openssl(
            directory,
            &[
                "pkcs12",
                "-export",
                "-inkey",
                "client.key",
                "-in",
                "client.pem",
                "-out",
                "client.p12",
                "-passout",
                "pass:core-env-proof",
            ],
        );
    }

    fn store(root: &Path) -> kms::KeyStore {
        kms::KeyStore::open(
            &root.join("store"),
            SealKey::derive(kms::SEAL_LABEL, b"core-env-proof-seal-material"),
        )
        .unwrap_or_else(|error| {
            panic!(
                "{}: {error:?}",
                "services/platform/hosted/internal/src/kms.rs: KeyStore must open the proof journal"
            )
        })
    }

    struct KmsServer {
        address: std::net::SocketAddr,
        stop: Arc<AtomicBool>,
        worker: Option<JoinHandle<()>>,
    }

    impl KmsServer {
        fn start(fixture: &mut Fixture) -> Self {
            for (suffix, file) in [
                ("TLS_CERT_DER", "server.der"),
                ("TLS_KEY_DER", "server-key.der"),
                ("CLIENT_CA_DER", "ca.der"),
                ("UPSTREAM_CA_DER", "ca.der"),
                ("UPSTREAM_TOKEN_FILE", "token"),
                ("UPSTREAM_CLIENT_IDENTITY_PKCS12", "client.p12"),
                ("UPSTREAM_CLIENT_IDENTITY_PASSWORD_FILE", "password"),
            ] {
                let path = fixture.root.join(file);
                fixture.set(&format!("{PREFIX}_{suffix}"), Some(path.as_os_str()));
            }
            let config = tls::server_config(PREFIX)
                .unwrap_or_else(|error| panic!("{}: {error:?}", "services/platform/hosted/internal/src/tls.rs: server_config must load the proof certificates"));
            let listener = TcpListener::bind("127.0.0.1:0").unwrap_or_else(|error| {
                panic!(
                    "{}: {error:?}",
                    "services/platform/hosted/internal/src/kms.rs: local producer must bind"
                )
            });
            fixture.text(
                &format!("{PREFIX}_UPSTREAM_URL"),
                &format!(
                    "https://localhost:{}",
                    listener
                        .local_addr()
                        .unwrap_or_else(|error| panic!("required value: {error:?}"))
                        .port()
                ),
            );
            let address = listener
                .local_addr()
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
            listener
                .set_nonblocking(true)
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
            let service =
                kms::Service::new(store(&fixture.root), Zeroizing::new(TOKEN.to_owned()), true);
            let stop = Arc::new(AtomicBool::new(false));
            let stopping = Arc::clone(&stop);
            let worker = thread::spawn(move || {
                while !stopping.load(Ordering::Acquire) {
                    let (socket, _) = match listener.accept() {
                        Ok(connection) => connection,
                        Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                            thread::sleep(Duration::from_millis(5));
                            continue;
                        }
                        Err(error) => panic!("KMS listener: {error}"),
                    };
                    socket
                        .set_read_timeout(Some(Duration::from_secs(5)))
                        .unwrap_or_else(|error| panic!("required value: {error:?}"));
                    socket
                        .set_write_timeout(Some(Duration::from_secs(5)))
                        .unwrap_or_else(|error| panic!("required value: {error:?}"));
                    let connection = rustls::ServerConnection::new(Arc::clone(&config))
                        .unwrap_or_else(|error| panic!("required value: {error:?}"));
                    let mut stream = rustls::StreamOwned::new(connection, socket);
                    let mut request = http::parse_client_request(&mut stream)
                        .unwrap_or_else(|error| panic!("required value: {error:?}"));
                    request.peer_verified = stream
                        .conn
                        .peer_certificates()
                        .is_some_and(|chain| !chain.is_empty());
                    assert!(
                        request.peer_verified,
                        "the real consumer must authenticate with mTLS"
                    );
                    http::write_response(&mut stream, &service.route(&request))
                        .unwrap_or_else(|error| panic!("required value: {error:?}"));
                    stream
                        .flush()
                        .unwrap_or_else(|error| panic!("required value: {error:?}"));
                    stream.conn.send_close_notify();
                    stream
                        .flush()
                        .unwrap_or_else(|error| panic!("required value: {error:?}"));
                }
            });
            Self {
                address,
                stop,
                worker: Some(worker),
            }
        }
    }

    fn create_key(fixture: &Fixture, server: &KmsServer) -> serde_json::Value {
        let ca = native_tls::Certificate::from_der(
            &fs::read(fixture.root.join("ca.der"))
                .unwrap_or_else(|error| panic!("required value: {error:?}")),
        )
        .unwrap_or_else(|error| panic!("required value: {error:?}"));
        let identity = native_tls::Identity::from_pkcs12(
            &fs::read(fixture.root.join("client.p12"))
                .unwrap_or_else(|error| panic!("required value: {error:?}")),
            "core-env-proof",
        )
        .unwrap_or_else(|error| panic!("required value: {error:?}"));
        let connector = native_tls::TlsConnector::builder()
            .disable_built_in_roots(true)
            .add_root_certificate(ca)
            .identity(identity)
            .build()
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        let socket = std::net::TcpStream::connect(server.address)
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        socket
            .set_read_timeout(Some(Duration::from_secs(5)))
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        socket
            .set_write_timeout(Some(Duration::from_secs(5)))
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        let mut stream = connector
            .connect("localhost", socket)
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        let body =
            serde_json::json!({"algorithm": "secp256k1", "purpose": "core-env-proof"}).to_string();
        write!(stream, "POST /v1/signing-keys HTTP/1.1\r\nHost: localhost\r\nAuthorization: Bearer {TOKEN}\r\nContent-Type: application/json\r\nIdempotency-Key: core-env-proof-key\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}", body.len(), body).unwrap_or_else(|error| panic!("required value: {error:?}"));
        stream
            .flush()
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        let response = http::read_http_message(&mut stream, 64 * 1024)
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        assert_eq!(response.headers[""].split_whitespace().nth(1), Some("201"));
        serde_json::from_slice(&response.body)
            .unwrap_or_else(|error| panic!("required value: {error:?}"))
    }

    impl Drop for KmsServer {
        fn drop(&mut self) {
            self.stop.store(true, Ordering::Release);
            if let Some(worker) = self.worker.take() {
                worker
                    .join()
                    .unwrap_or_else(|error| panic!("required value: {error:?}"));
            }
        }
    }

    fn check_key_file_sources(fixture: &mut Fixture) -> (PathBuf, [TcpListener; 2]) {
        let listeners = [
            TcpListener::bind("127.0.0.1:0")
                .unwrap_or_else(|error| panic!("required value: {error:?}")),
            TcpListener::bind("127.0.0.1:0")
                .unwrap_or_else(|error| panic!("required value: {error:?}")),
        ];
        let key_path = fixture.private_file("sender.key", b"initially-not-a-key");
        fixture.set(
            LAYERX_CORE_FUNDING_SENDER_KEY_FILE,
            Some(key_path.as_os_str()),
        );
        let mut previous_address = None;
        for (index, listener) in listeners.iter().enumerate() {
            let address = listener
                .local_addr()
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
            fixture.text(LAYERX_CORE_CHAIN_RPC_URL, &format!("http://{address}"));
            let account = derive_from_seed(
                &[0x51; 32],
                u32::try_from(index).unwrap_or_else(|error| panic!("required value: {error:?}")),
            )
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
            let encoded = Zeroizing::new(super::hex_encode(
                account
                    .evm_secret()
                    .unwrap_or_else(|| panic!("required value")),
            ));
            fs::write(&key_path, encoded.as_bytes())
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
            for _ in 0..2 {
                let decoded = FundingEnvironment::from_env()
                    .unwrap_or_else(|error| panic!("required value: {error:?}"));
                assert_eq!(decoded.endpoint.host, address.ip().to_string());
                assert_eq!(decoded.endpoint.port, address.port());
                assert_eq!(decoded.sender.address(), account.evm_address());
                assert_ne!(Some(decoded.sender.address()), previous_address);
                assert!(ChainFunding::from_env().is_ok());
            }
            previous_address = Some(account.evm_address());
        }
        (key_path, listeners)
    }

    #[test]
    fn proof_core_env_vars_producer_transport_consumer() {
        let mut fixture = Fixture::new();
        let (key_path, listeners) = check_key_file_sources(&mut fixture);

        // A previous successful decode must not mask a changed or corrupt producer.
        fs::write(&key_path, "00".repeat(32))
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        for _ in 0..2 {
            assert_eq!(
                FundingEnvironment::from_env().err(),
                Some("sender_unavailable")
            );
            assert_eq!(ChainFunding::from_env().err(), Some("sender_unavailable"));
        }
        for malformed in [
            "",
            "https://127.0.0.1:125",
            "http://example.com:125",
            "http://127.0.0.1:125/path",
            "http://127.0.0.1:bad",
        ] {
            fixture.text(LAYERX_CORE_CHAIN_RPC_URL, malformed);
            assert_eq!(ChainFunding::from_env().err(), Some("chain_unavailable"));
        }
        fixture.text(
            LAYERX_CORE_CHAIN_RPC_URL,
            &format!(
                "http://{}",
                listeners[0]
                    .local_addr()
                    .unwrap_or_else(|error| panic!("required value: {error:?}"))
            ),
        );
        fixture.set(LAYERX_CORE_FUNDING_SENDER_KEY_FILE, None);
        for malformed in ["", "invalid key", "kms-secp256k1-not-an-id"] {
            fixture.text(LAYERX_CORE_FUNDING_SENDER_KMS_KEY_ID, malformed);
            assert_eq!(
                EvmSender::from_env(PREFIX).err(),
                Some(EvmSenderError::InvalidKmsHandle)
            );
            assert_eq!(ChainFunding::from_env().err(), Some("sender_unavailable"));
        }

        certificates(&fixture.root);
        fixture.private_file("token", TOKEN.as_bytes());
        fixture.private_file("password", b"core-env-proof");
        // The producer emits the identifier and public key; no response is fabricated.
        let producer = KmsServer::start(&mut fixture);
        let created = create_key(&fixture, &producer);
        let key_id = created["key_id"]
            .as_str()
            .unwrap_or_else(|| panic!("required value"));
        let public = base64::decode(
            created["public_key"]
                .as_str()
                .unwrap_or_else(|| panic!("required value")),
        )
        .unwrap_or_else(|| panic!("required value"));
        let expected = layerx_crypto::secp256k1::evm_address(&public)
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        drop(producer); // Close the producer journal before the consumer loads the key.
        let server = KmsServer::start(&mut fixture);
        fixture.text(LAYERX_CORE_FUNDING_SENDER_KMS_KEY_ID, key_id);
        for _ in 0..2 {
            let decoded = FundingEnvironment::from_env()
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
            assert_eq!(decoded.sender.address(), expected);
            assert!(ChainFunding::from_env().is_ok());
            let digest = [0x71; 32];
            let signature = decoded
                .sender
                .sign_prehash(&digest)
                .unwrap_or_else(|error| panic!("required value: {error:?}"));
            layerx_crypto::secp256k1::verify_recoverable_digest(
                &public,
                &signature[..64]
                    .try_into()
                    .unwrap_or_else(|error| panic!("required value: {error:?}")),
                signature[64],
                &digest,
            )
            .unwrap_or_else(|error| panic!("required value: {error:?}"));
        }
        fixture.text(LAYERX_CORE_FUNDING_SENDER_KMS_KEY_ID, "whk_unknown");
        for _ in 0..2 {
            assert_eq!(
                EvmSender::from_env(PREFIX).err(),
                Some(EvmSenderError::KmsUnavailable)
            );
            assert_eq!(ChainFunding::from_env().err(), Some("sender_unavailable"));
        }
        fixture.text(LAYERX_CORE_FUNDING_SENDER_KMS_KEY_ID, key_id);
        fixture.set(
            LAYERX_CORE_FUNDING_SENDER_KEY_FILE,
            Some(key_path.as_os_str()),
        );
        assert_eq!(
            EvmSender::from_env(PREFIX).err(),
            Some(EvmSenderError::AmbiguousSource)
        );
        assert_eq!(ChainFunding::from_env().err(), Some("sender_unavailable"));
        drop(server);
    }
}
